void stamp(const std::filesystem::path& path,uint64_t ticks){HANDLE h=CreateFileW(path.c_str(),FILE_WRITE_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,0,nullptr);check(h!=INVALID_HANDLE_VALUE,"Stamp fixture open");FILETIME t{DWORD(ticks),DWORD(ticks>>32)};const auto ok=SetFileTime(h,nullptr,nullptr,&t);CloseHandle(h);check(ok,"Stamp fixture write");}
