    const auto cleaned=currentLog(root,token);for(const auto* value:{"PrivatePerson","model.bin","latitude","person@example.com","hidden"})check(cleaned.find(value)==std::string::npos,"Private field was not removed");check(cleaned.find("frames=100")!=std::string::npos,"Diagnostic frame data was lost");
