    FILETIME now{};GetSystemTimeAsFileTime(&now);const auto ticks=fileTime(now);const auto log=std::filesystem::path(p.simulator)/L"Log.txt";std::filesystem::create_directories(log.parent_path());const auto xp=std::string("Log.txt for X-Plane 12.4.4\nGPU test\npath=C:\\Users\\PrivatePerson\\sim\n");graphics::write(log,xp);stamp(log,ticks);
    check(textSnapshot(log,ticks-10000000,ticks+10000000,true).find("GPU test")!=std::string::npos,"Matching Log.txt omitted");check(textSnapshot(log,ticks+10000000,ticks+20000000,true).empty(),"Stale Log.txt attached");check(textSnapshot(log,ticks-100000000,ticks-40000000,true).empty(),"Newer-launch Log.txt attached");graphics::write(log,"Not an X-Plane log");check(textSnapshot(log,0,UINT64_MAX-30000000,true).empty(),"Foreign Log.txt accepted");graphics::write(log,xp);stamp(log,ticks);
