    const auto files=diagnosticFiles(root,token,GetCurrentProcessId());const auto json=fileJson(files);check(json.find("diagnostics.txt")!=std::string::npos&&json.find("startup-errors.txt")!=std::string::npos&&json.find("native-aa-settings.txt")!=std::string::npos,"Helpful diagnostic files missing");check(json.find("PrivatePerson")==std::string::npos&&json.find("private.dmp")==std::string::npos&&json.find("Never upload") ==std::string::npos,"Private or binary files included");
