    int submitted=0;auto submit=[&](const auto& render,const auto& target,const auto&,const auto&,const auto& extras){++submitted;check(render==cleaned&&target=="bugs"&&!extras.empty(),"Queued report did not use exact consented diagnostic choices");};
    sendQueued(root,token,GetCurrentProcessId(),submit);check(submitted==0,"Default-Off reported without consent");queue(root,token,"bugs","Synthetic bug",true);cancel(root,token);sendQueued(root,token,GetCurrentProcessId(),submit);check(submitted==0,"Cancelled report was sent");
    queue(root,token,"bugs","Synthetic bug",true);sendQueued(root,token,GetCurrentProcessId(),submit);sendQueued(root,token,GetCurrentProcessId(),submit);check(submitted==1,"Automatic report repeated");
